#include<vector>
using namespace std;

int main() {
    int n, cnt;

    while (cin >> n) {
        if (n < 2) {
            cout << 0 << endl; // Return 0 for cases where n < 2
            continue;
        }

        vector<bool> prime(n + 1, true); // Initialize all numbers as prime
        prime[0] = prime[1] = false; // 0 and 1 are not prime

        for (int j = 2; j * j <= n; j++) {
            if (prime[j]) {
                for (int k = j * j; k <= n; k += j) {
                    prime[k] = false; // Mark non-prime numbers
                }
            }
        }

        cnt = 0;
        for (int i = 2; i <= n; i++) { // Start counting from 2
            if (prime[i]) cnt++;
        }

        cout << cnt << endl;
    }
}

