using namespace std;

int main() {
    int n;
    while (cin >> n) {
        if (n < 2) {
            cout << 0 << endl; // No primes less than 2
            continue;
        }

        bool* prime = new bool[n + 1](); // Initializes all to false
        prime[1] = true; // 1 is not prime

        for (int j = 2; j * j <= n; j++) {
            if (!prime[j]) {
                for (int k = j * j; k <= n; k += j) {
                    prime[k] = true; // Marking non-primes as true
                }
            }
        }

        int cnt = 0;
        for (int i = 1; i <= n; i++) {
            if (!prime[i]) cnt++;
        }

        cout << cnt << endl;
        delete[] prime; // Free dynamically allocated memory
    }
}

